17	package org.springframework.samples.petclinic.util;
18	
19	/**
20	 * Derives an owner's {@code membershipTier} from their namesake count and email address.
21	 */
22	public final class MembershipTierFormatter {
23	
24	    private static final String SILVER = "SILVER";
25	
26	    private static final String BRONZE = "BRONZE";
27	
28	    private MembershipTierFormatter() {
29	    }
30	
31	    /**
32	     * Return the membership tier: {@code "SILVER"} when the owner has no namesakes
33	     * ({@code namesakeCount} is {@code 0}) and an email address is present, otherwise
34	     * {@code "BRONZE"}.
35	     *
36	     * @param namesakeCount the number of owners sharing this owner's name, may be {@code null}
37	     * @param email         the owner's email address, may be {@code null}
38	     * @return {@code "SILVER"} or {@code "BRONZE"}
39	     */
40	    public static String format(Integer namesakeCount, String email) {
41	        boolean unique = namesakeCount != null && namesakeCount == 0;
42	        boolean hasEmail = email != null && !email.isBlank();
43	        return unique && hasEmail ? SILVER : BRONZE;
44	    }
45	}
