238	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
239	        if (ownerRepository.existsByTelephone(owner.getTelephone())) {
240	            throw new DuplicateTelephoneException(owner.getTelephone());
241	        }
242	        List<Owner> householdMembers = findHouseholdMembers(owner);
243	        if (!householdMembers.isEmpty() && !sharesHousehold) {
244	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
245	        }
246	        owner.setNamesakeCount(countNamesakes(owner));
247	        if (owner.getRegistrationDate() == null) {
248	            owner.setRegistrationDate(LocalDate.now());
249	        }
250	        owner.setCustomerCode(
251	            CustomerCodeGenerator.format(owner.getLastName(), ownerRepository.count() + 1));
252	        if (!householdMembers.isEmpty()) {
253	            owner.setHouseholdId(joinHousehold(owner, householdMembers));
254	        }
255	        ownerRepository.save(owner);
256	        return owner.getHouseholdId();
257	    }
258	
259	    /**
260	     * Assign the stable household identifier to the new owner and to every existing member of the
261	     * household, persisting the members whose identifier changes, and return the shared identifier.
262	     */
263	    private String joinHousehold(Owner owner, List<Owner> householdMembers) {
264	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
265	        for (Owner member : householdMembers) {
266	            if (!householdId.equals(member.getHouseholdId())) {
267	                member.setHouseholdId(householdId);
268	                ownerRepository.save(member);
269	            }
270	        }
271	        return householdId;
272	    }
273	
274	    @Override
275	    @Transactional
276	    public void saveOwner(Owner owner) throws DataAccessException {
277	        ownerRepository.save(owner);
278	    }
279	
280	    /**
281	     * Count the owners that already exist sharing this owner's first name and last name, compared
282	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
283	     */
284	    private int countNamesakes(Owner owner) {
285	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
286	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
287	            .count();
288	    }
289	
290	    /**
291	     * Find the existing owners that already share this owner's household, i.e. that have the same last name and
292	     * address compared case-insensitively and with runs of whitespace collapsed.
293	     */
294	    private List<Owner> findHouseholdMembers(Owner owner) {
295	        String address = TextNormalizer.normalize(owner.getAddress());
296	        if (address == null) {
297	            return List.of();
298	        }
299	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
300	            .filter(existing -> address.equals(TextNormalizer.normalize(existing.getAddress())))
301	            .toList();
302	    }
303	
